document.addEventListener('click',(event)=>{const button=event.target.closest('.frs-product-card-alpha .quantity .action');if(!button)return;const input=button.parentElement.querySelector('input.qty');if(!input)return;const step=Number.parseInt(input.step||'1',10)||1;const min=Number.parseInt(input.min||'1',10)||1;const max=input.max?Number.parseInt(input.max,10):Number.POSITIVE_INFINITY;const current=Number.parseInt(input.value||String(min),10)||min;const next=button.classList.contains('plus')?Math.min(max,current+step):Math.max(min,current-step);if(next===current)return;input.value=String(next);input.dispatchEvent(new Event('change',{bubbles:!0}))})